var SessionTimeOut = 0;
var labelPrinterExecutablefileUrl = "http://localhost:5005";

(function getConfig() {

    var xhr = new XMLHttpRequest();
    xhr.open("get", "appconfig.json", window);
    xhr.onload = function () {
        var status = xhr.status;
        if (status === 200) {
            if (xhr.responseText) {
                var response = JSON.parse(xhr.responseText);
                window.url = response.urls.apiurl;
                SessionTimeOut = response.urls.SessionTimeOut;
            }
        } else {
            console.error("messages: Could not load confguration -> ERROR ->", status);
        }
    };
    xhr.send();
}
)();


eHnoteServices.factory("downloadpdfService", ['$http', function ($http) {
    return {
        downloadPdf: function (url) {
            return $http.get(url, { responseType: 'arraybuffer' })
                .then(function (response) {
                    return response;
                });
        }
    };
}]);

