eHnoteServices.service("eHnoteUserDataService", ["$http", "datapersistanceFactory", "eHnoteMasterDataService", "eHnoteLoginObjService", function ($http, datapersistanceFactory, eHnoteMasterDataService, eHnoteLoginObjService) {
    doctorinfo = eHnoteMasterDataService.getUserInfo();
    this.getspeciality = function (callbacksuccess, callbackerror) {
        $http.get(url + "/MasterData/GetAllSpeciality", header).success(function (data) {
            callbacksuccess(data);
        }).error(function (data) {
            callbackerror(data);
        });
    };

    this.getmasterspeciality = function () {
        return $http.get(url + "/MasterData/GetAllSpeciality");
    };

    this.getOrgOpthalDepartments = function (params, callbackSuccess, callbackError) {
        //params = JSON.stringify(params);
        //params = "'" + params + "'";

        $http.get(url + "/MasterData/getMasterOrgOpthalDepartments?ParentOrganizationId=" + params.ParentOrganizationId).then(function successCallback(response) {
            callbackSuccess(response);
        }, function errorCallback(response) {
            callbackError(response);
        });
    };
    this.EvaluateUserInfo = function (data) {
        //return EvaluateUserInfo(data, true);



        var docArrObjj = data.User;
        var docSpecialityObj = data.UserSpecilityDetails;
        if (docArrObjj !== null) {
            var docObjj = docArrObjj[0];
            var doctorid = docObjj.DoctorID;
            var mailArrobj = data.UserEmail;
            var emailid = (mailArrobj !== null || mailArrobj !== undefined) ? mailArrobj[0].EmailID : "";
            //if (loadallmappedinfo) {
            //    GetAllMappedInfoByDoctorId(doctorid, data);
            //}
            var doctorinfo = eHnoteMasterDataService.getUserInfo();

            doctorinfo.doctorid = doctorid;
            doctorinfo.UserLoginID = docObjj.UserLoginID;
            doctorinfo.specialitycode = docSpecialityObj;
            if (data.UserSetting) {
                doctorinfo.UserSetting = data.UserSetting;
            }
            data.UserAddress = data.UserAddress || [];
            if (data.UserAddress.length > 0) {




                doctorinfo.groupID = (data.UserAddress[0].ExtDetails.GroupID !== undefined) ? data.UserAddress[0].ExtDetails.GroupID : "";
                doctorinfo.hospitalID = data.UserAddress[0].ExtDetails.HospitalID;
                doctorinfo.RoleName = (data.UserAddress[0].ExtDetails.RoleName !== undefined) ? data.UserAddress[0].ExtDetails.RoleName : "";
                doctorinfo.RoleID = (data.UserAddress[0].ExtDetails.RoleID !== undefined) ? data.UserAddress[0].ExtDetails.RoleID : "";
                doctorinfo.RoleDesc = (data.UserAddress[0].ExtDetails.RoleDesc !== undefined) ? data.UserAddress[0].ExtDetails.RoleDesc : "";
                doctorinfo.GroupName = (data.UserAddress[0].ExtDetails.GroupName !== undefined) ? data.UserAddress[0].ExtDetails.GroupName : "";
                if (doctorinfo.hospitalID) {
                    doctorinfo.isUserHavingAccess = true;
                }
                if (data.UserAddress[0].ExtDetails.UserAccessID !== undefined) {
                    doctorinfo.isUserHavingAccess = true;
                    angular.forEach(data.UserAddress[0].ExtDetails.UserAccessID, function (value, key) {
                        this.push(value);
                    }, doctorinfo.UserAccessID);
                }
            }
            doctorinfo.doctordata = data;
            doctorinfo.specialisation = data && data.User ? data.User[0].SpecializationName : "";
            doctorinfo.SignOffPWDInd = data.User[0].SignOffPWDInd;
            doctorinfo.SignOffPassword = data.User[0].SignOffPassword;
            eHnoteMasterDataService.addUserInfo(doctorinfo);
            eHnoteMasterDataService.addLoginId(doctorid);
            var logininfo = eHnoteLoginObjService.getProfileInfo();
            logininfo.doctorid = doctorid;
            logininfo.memberid = docObjj.MemberID;
            logininfo.specialitycode = docSpecialityObj;
            eHnoteLoginObjService.addProfileInfo(logininfo);
            return true;
        } else {
            return false;
        }
    };


    Array.prototype.unique = function () {
        var a = this.concat();
        for (var i = 0; i < a.length; ++i) {
            for (var j = i + 1; j < a.length; ++j) {
                if (a[i].$$hashKey) {
                    delete a[i].$$hashKey;
                }
                if (a[j].$$hashKey) {
                    delete a[j].$$hashKey;
                }
                if (a[i] === a[j]) {
                    a.splice(j--, 1);
                }
            }
        }
        return a;
    };

    this.EvaluateUserAccessRights = function (mainobject, DefaultTabId) {


        console.log(DefaultTabId);

        var NewAccessRightsObj = {
            "MainAccessCategories": [],
            "SubAccessCategories": [],
            "AccessRights": angular.copy(mainobject.AccessRights),
            "DefaultTabId": DefaultTabId
        };






        var DistinctSubAccessCategories = _.uniq(mainobject.AccessCategoryList, false, function (p) { return p.SubAccessCategoryId; });
        var DistinctMainAccessCategories = _.uniq(mainobject.AccessCategoryList, false, function (p) { return p.MainAccessCategoryId; });

        angular.forEach(DistinctSubAccessCategories, function (sitem) {
            var obj = {
                "SubAccessCategoryId": sitem.SubAccessCategoryId,
                "MainAccessCategoryId": sitem.MainAccessCategoryId,
                "ActiveInd": 'Y'
            }
            NewAccessRightsObj.SubAccessCategories.push(obj);
        });

        angular.forEach(DistinctMainAccessCategories, function (sitem) {
            var obj = {
                "SubAccessCategoryId": sitem.SubAccessCategoryId,
                "MainAccessCategoryId": sitem.MainAccessCategoryId,
                "ActiveInd": 'Y'
            }
            NewAccessRightsObj.MainAccessCategories.push(obj);
        });





        eHnoteMasterDataService.addUserAppPermissions(NewAccessRightsObj);

        return true;

    };





    this.UsMobileFormatChange = function (data) {
        var USnumberString = "";
        var UsFormatMobileNumber = "";
        USnumberString = data || "";
        if (USnumberString != "") {
            const match = data
                .replace(/\D+/g, '')
                .match(/([^\d]*\d[^\d]*){1,10}$/)[0]
            const part1 = match.length > 3 ? `(${match.substring(0, 3)})` : match
            const part2 = match.length > 3 ? ` ${match.substring(3, 6)}` : ''
            const part3 = match.length > 6 ? `-${match.substring(6, 10)}` : ''
            UsFormatMobileNumber = part1 + part2 + part3;

        }

        var obj = {
            "MobileNumber": USnumberString,
            "UsFormatMobileNumber": UsFormatMobileNumber
        };

        return obj;
    };
    this.FaxUsMobileFormatChange = function (data) {
        var USnumberString = "";
        var UsFormatMobileNumber = "";

        USnumberString = data || "";
        if (USnumberString !== "") {
            // Strip non-digits
            const digits = data.replace(/\D+/g, '');
            if (digits.length > 0) {
                // Take only last 10 digits (US format)
                const match = digits.slice(-10);

                const part1 = match.length > 3 ? `(${match.substring(0, 3)})` : match;
                const part2 = match.length > 3 ? ` ${match.substring(3, 6)}` : '';
                const part3 = match.length > 6 ? `-${match.substring(6, 10)}` : '';
                UsFormatMobileNumber = part1 + part2 + part3;
                USnumberString = match; // store just the clean 10-digit number
            }
        }

        var obj = {
            "MobileNumber": USnumberString,
            "UsFormatMobileNumber": UsFormatMobileNumber
        };

        return obj;
    };

}]);
