    this.RestructureOrganizationSettings = function (SettingsData, orgresp) {
        orgresp = orgresp || ''
        let IsClinicalVisitType = false;
        if (orgresp != '') {
            orgresp.IsClinicalVisitType = orgresp.IsClinicalVisitType || false;
            IsClinicalVisitType = orgresp.IsClinicalVisitType || false;
        }
        console.log(SettingsData);
        console.log("SettingsData");
        var OrganizationSettingsData = {
            "BillingSettings": {
                "AppointmentBilling": [{
                    "Id": 1,
                    "Name": "Discount",
                    "Status": false
                },
                {
                    "Id": 2,
                    "Name": "GST",
                    "Status": false
                }],
                "SurgeryBilling": [{
                    "Id": 1,
                    "Name": "Discount",
                    "Status": false
                },
                {
                    "Id": 2,
                    "Name": "GST",
                    "Status": false
                }],
                "IsChargeEditedInd": false,
                "IsSecondaryChargeEditInd": false,
                "IsBillingMandatoryForStartConsultation": 0,
                "CheckAppointmentInsuranceEligibilityAutomatic": 0,
                "IsDueAmountShow": 0
            },
            "AppointmentSettings": {
                "AppointmentCheckInDynamicStatus": 1,
                "SelectSlotDuration": "15m",
                "DigitalSigatureType": "Drawing"
            },
            "PatientRegistration": {
                "IsEmergencyContactMandatory": 0,
                "IsMobileNoManadatory": 0,
                "IsRefferalSourceMandatory": 0,
                "IsAddressDetailsMandatory": 0,
                "IsSecondLastNameMandatory": 0,
                "IsNoChargePatientMandatory": 0,
                "IsPreviousNameMandatory": 0,
                "IsFirstNameNoManadatory": 0,
                "IsMiddleNameNoManadatory": 0,
                "IsLastNameNoManadatory": 0,
                "IsDOBNoManadatory": 0,
                "IsGenderNoManadatory": 0,
                "IsEmailIdNoManadatory": 0,
                "IsAlternativeNumberNoManadatory": 0,
                "IsEmployerNameNoManadatory": 0,
                "IsEmployerPhoneNumberNoManadatory": 0,
                "IsOccupationNoManadatory": 0,
                "IsAddressDetailsNoManadatory": 0,

                "IsCoverageNoManadatory": 0,
                "IsPlannameNoManadatory": 0,
                "IsPayornameNoManadatory": 0,
                "IsPolicyIDNoManadatory": 0,
                "IsGroupIDNoManadatory": 0,
                "IsEffectivedateNoManadatory": 0,
                "IsExpirydateNoManadatory": 0
            },
            "ConsultationSettings": {
                "IsConsultationRestricted": 0,
                "IsRosCarrieForword": 0,
            },
            "ProfileStatusSettings": {
                "IsProfileStatusRestricted": 0,
                "ProfileStatusArray": []
            },
            "IsClinicalVisitType": false,

        };

        datapersistanceFactory.set("OrganizationSettingsData", OrganizationSettingsData);
        if (angular.equals(SettingsData, {})) {
            datapersistanceFactory.set("OrganizationSettingsData", OrganizationSettingsData);
        } else {
            if (SettingsData.BillingSettings !== undefined) {

                if (SettingsData.BillingSettings.AppointmentBilling === undefined) {
                    SettingsData.BillingSettings.AppointmentBilling = OrganizationSettingsData.BillingSettings.AppointmentBilling;
                }
                if (SettingsData.BillingSettings.SurgeryBilling === undefined) {
                    SettingsData.BillingSettings.SurgeryBilling = OrganizationSettingsData.BillingSettings.SurgeryBilling;
                }
                SettingsData.BillingSettings = SettingsData.BillingSettings ? SettingsData.BillingSettings : OrganizationSettingsData.BillingSettings;
                SettingsData.BillingSettings.IsBillingMandatoryForStartConsultation = SettingsData.BillingSettings.IsBillingMandatoryForStartConsultation || 0;
                SettingsData.BillingSettings.CheckAppointmentInsuranceEligibilityAutomatic = SettingsData.BillingSettings.CheckAppointmentInsuranceEligibilityAutomatic || 0;


                SettingsData.BillingSettings.IsChargeEditedInd = SettingsData.BillingSettings.IsChargeEditedInd || false;

                SettingsData.BillingSettings.IsSecondaryChargeEditInd = SettingsData.BillingSettings.IsSecondaryChargeEditInd || false;

                SettingsData.BillingSettings.IsDueAmountShow = SettingsData.BillingSettings.IsDueAmountShow || 0;
                SettingsData.AppointmentSettings = SettingsData.AppointmentSettings ? SettingsData.AppointmentSettings : OrganizationSettingsData.AppointmentSettings;

                SettingsData.ConsultationSettings = SettingsData.ConsultationSettings ? SettingsData.ConsultationSettings : OrganizationSettingsData.ConsultationSettings;

                SettingsData.ProfileStatusSettings = SettingsData.ProfileStatusSettings != undefined ? SettingsData.ProfileStatusSettings : OrganizationSettingsData.ProfileStatusSettings;
                SettingsData.IsClinicalVisitType = IsClinicalVisitType || false;
                datapersistanceFactory.set("OrganizationSettingsData", SettingsData);
            }
        }
    };
