    this.NewGetLandingScreen = function () {


        var UserAccessRights = eHnoteMasterDataService.getUserAppPermissions();

        console.log(UserAccessRights.DefaultTabId);


        UserAccessRights.DefaultTabId = parseFloat(UserAccessRights.DefaultTabId) || "";
        if (UserAccessRights.MainAccessArray.length > 0) {
            var defaulttabhaving = false;
            angular.forEach(UserAccessRights.MainAccessArray, function (mainitem) {
                if (mainitem.MainAccessCategoryId === UserAccessRights.DefaultTabId) {
                    defaulttabhaving = true;
                }
            });

            if (!defaulttabhaving) {
                UserAccessRights.DefaultTabId = UserAccessRights.MainAccessArray[0].MainAccessCategoryId;
            }
        }

        console.log(UserAccessRights.DefaultTabId + "_DefaultTabId");

        var Location = null;
        if (UserAccessRights.DefaultTabId === 2) {
            Location = "/op";
        } else if (UserAccessRights.DefaultTabId === 3) {
            Location = "/OT";
        } else if (UserAccessRights.DefaultTabId === 4) {
            //Location = "/Counsellor"; 
            Location = "/Coordinator"; // using the word 'Coordinator' for US development
        } else if (UserAccessRights.DefaultTabId === 5) {
            Location = "/Biller";
        } else if (UserAccessRights.DefaultTabId === 6) {
            eHnoteMasterDataService.AddTypeOfVendor("I");
            Location = "/Pharmacy";
        } else if (UserAccessRights.DefaultTabId === 7) {
            eHnoteMasterDataService.AddTypeOfVendor("H");
            Location = "/Inventory";
        } else if (UserAccessRights.DefaultTabId === 8) {
            eHnoteMasterDataService.AddTypeOfVendor("O");
            Location = "/Optical";
        } else if (UserAccessRights.DefaultTabId === 9) {
            Location = "/settings";
        } else if (UserAccessRights.DefaultTabId === 10) {
            Location = "/Communication";
        } else if (UserAccessRights.DefaultTabId === 11) {
            Location = "/Pettycash";
        } else if (UserAccessRights.DefaultTabId === 12) {
            Location = "/audit";
        } else if (UserAccessRights.DefaultTabId === 13) {
            Location = "/admin";
        } else if (UserAccessRights.DefaultTabId === 14) {
            Location = "/crm";
        } else if (UserAccessRights.DefaultTabId === 15) {
            Location = "/Referal";
        } else {
            Location = "/dashboard";
        }


        return Location;
    };
