    this.AddUpdatePortalBranding = function (params, callbackSuccess, callbackError) {
        $http({
            method: "POST",
            url: url + "/Setting/AddupdatePortalLogoColourBranding",
            headers: { "Content-Type": undefined },
            transformRequest: function (data) {
                var formData = new FormData();

                // Send full model as JSON string
                formData.append("model", angular.toJson(data.model));

                // Append files if exists
                if (data.model.logoFile) {
                    formData.append("logoFile", data.model.logoFile);
                }

                if (data.model.faviconFile) {
                    formData.append("faviconFile", data.model.faviconFile);
                }

                return formData;
            },
            data: { model: params }
        }).success(function (res) {
            if (res !== null && res.ExceptionType !== "PSQLException") {
                callbackSuccess(res);
            }
        }).error(function (err) {
            callbackError(err);
        });
    };


