    this.DiscountOrGSTEnabledObject = function (BillingDetailArray) {
        var TempBillingDetailArray = angular.copy(BillingDetailArray);
        var object = { "IsDiscountChecked": false, "IsGSTChecked": false };
        var GSTCheckedCount = 0, DiscountCheckedCount = 0;
        angular.forEach(TempBillingDetailArray, function (item, index) {
            item.DiscountCost = parseFloat(item.DiscountCost) || 0;
            item.Cgst = parseFloat(item.Cgst) || 0;
            item.Sgst = parseFloat(item.Sgst) || 0;
            if (item.DiscountCost !== 0) {
                DiscountCheckedCount++;
            }
            if (item.Cgst !== 0 && item.Sgst !== 0) {
                GSTCheckedCount++;
            }
        });
        if (DiscountCheckedCount > 0) {
            object.IsDiscountChecked = true;
        }
        if (GSTCheckedCount > 0) {
            object.IsGSTChecked = true;
        }
        return object;
    };

