        this.AddUpdatePatientClaimNew = function (mainBillingParams, callbackSuccess, callbackError) {

            /* url: url + "/Insurance/AddUpdatePatientClaimv2",*/
            $http({
                method: "POST",
                url: url + "/Insurance/AddUpdatePatientClaimv2",
                headers: { "Content-Type": undefined },
                transformRequest: function (data) {
                    var formData = new FormData();
                    formData.append("model", angular.toJson(data.model));
                    for (var i = 0; i < data.model.TempDocumentDetails.length; i++) {
                        formData.append("file", data.model.TempDocumentDetails[i].file);
                    }
                    return formData;
                },
                data: { model: mainBillingParams, file: mainBillingParams.DocumentDetails }
            }).success(function (patData) {
                if (patData !== null && patData.ExceptionType !== "PSQLException") {
                    callbackSuccess(patData);
                }
            }).error(function (patData) {
                callbackError(patData);
            });


        };

