        function GetPatient(param, callbackSuccess, callbackError, appintmentSearch) {
            appintmentSearch = appintmentSearch || false;
            var searchText = "FullName";
            var searchValue = param.FirstName;
            if (param.PhoneNumber !== undefined) {
                if (param.PhoneNumber !== "" && param.PhoneNumber.length > 0) {
                    searchText = "PhNumber";
                    searchValue = param.PhoneNumber;
                }
            }
            if (param.PhoneNumber === "") {
                param.PhoneNumber = undefined;
            } else {
                param.FirstName = param.FirstName;
            }
            param = JSON.stringify(param);
            param = "'" + param + "'";
            var urlpath = $http.post(url + "/Patient/GetPatientsForAutocomplete", param, header);
            urlpath.success(function (data) {
                callbackSuccess(data);
            }).error(function (data) {
                callbackError(data);
            });
        }


