        this.ModifyPaymentsArray = function (PaymentsArray) {
            var i = PaymentsArray.length;
            while (i--) {
                PaymentsArray[i].Amount = parseFloat(PaymentsArray[i].Amount) || 0;
                if (PaymentsArray[i].Amount === 0) {
                    if (PaymentsArray[i].PaymentModeId !== 1) {
                        PaymentsArray.splice(i, 1);
                    }
                }
            }
            if (PaymentsArray.length > 1) {
                var j = PaymentsArray.length;
                while (j--) {
                    PaymentsArray[j].Amount = parseFloat(PaymentsArray[j].Amount) || 0;
                    if (PaymentsArray[j].Amount === 0) {
                        PaymentsArray.splice(j, 1);
                    }
                }
            }
            return PaymentsArray;
        };

