        this.GetFollowUpDate = function (days, type, AppointmentDt) {
            //var followup = 0;
            //if (type === "Y") {
            //    followup = 365 * days;
            //} else if (type === "M") {
            //    followup = 30 * days;
            //} else if (type === "W") {
            //    followup = 7 * days;
            //} else if (type === "D") {
            //    followup = 1 * days;
            //}
            //let d = AppointmentDt + " " + "00:00:00";
            //var pastdate = new Date(d);
            //pastdate.setDate(pastdate.getDate() + followup);

            var followup = 0;
            let d = AppointmentDt + " " + "00:00:00";
            let newDate = moment(d);

            if (type === "Y") {
                followup = 365 * days;
                newDate = newDate.add(days, 'years');
            } else if (type === "M") {
                followup = 30 * days;
                newDate = newDate.add(days, 'months');
            } else if (type === "W") {
                followup = 7 * days;
                newDate = newDate.add(days, 'weeks');
            } else if (type === "D") {
                followup = 1 * days;
                newDate = newDate.add(days, 'days');
            }

            //if (days === 0) {
            //    return { "FollowUpDate": null, "followup": followup };
            //} else {
            //    return { "FollowUpDate": moment(newDate).format("DD-MMM-YYYY"), "followup": followup };
            //}
            return { "FollowUpDate": moment(newDate).format("DD-MMM-YYYY"), "followup": followup };
        };
        this.IsFutureDate = function (future) {
            var today = moment(new Date());
            //var future = moment(date);
            //var diffcount = future.diff(today, "days") + 1;


            today = moment(new Date()).format("YYYYMMDD");
            future = moment(future).format("YYYYMMDD");


            if (parseInt(future) > parseInt(today)) {
                return true;
            } else {
                return false;
            }

            //if (diffcount > 0) {//Future Date Or Current Date
            //    return true;
            //} else {//Not Future Date
            //    return false;
            //}


        };
