        this.UpdateClaimTransmissionStatus = function (param, callbackSuccess, callbackError) {

            $http({
                method: "POST",
                url: url + "/Insurance/UpdateClaimTransmissionStatus",
                headers: { "Content-Type": undefined },
                transformRequest: function (data) {
                    var formData = new FormData();
                    formData.append("model", angular.toJson(data.model));

                    for (var i = 0; i < data.model.PatientDocumentDetails.length; i++) {
                        if (data.model.PatientDocumentDetails[i].AttachmentId == 0) {
                            if (data.model.PatientDocumentDetails[i].file !== "" && data.model.PatientDocumentDetails[i].file !== undefined) {
                                formData.append("file", data.model.PatientDocumentDetails[i].file);
                            }
                        }
                    }
                    return formData;
                },
                data: { model: param }
            }).success(function (patData) {
                callbackSuccess(patData);
            }).error(function (patData) {
                callbackError(patData);
            });
        };


