eHnoteServices.service("eHnoteUserProfileService", ['$http', '$q', 'eHnoteDbStaticDataService', 'eHnoteUserDataService', function ($http, $q, eHnoteDbStaticDataService, eHnoteUserDataService) {
    this.SaveUserProfile = function (doctorinfo, page, callbackSuccess, callbackError) {
        var doctorDetails = {
            DoctorID: doctorinfo.doctorid,
            TermsAccepted: "Y"
        };
        var params = {
            USRType: "DOCTOR",
            UserId: doctorinfo.doctorid,
            UserDetails: doctorDetails,
            ResetPassWord: doctorinfo.ResetPassWord ? true : false
        };
        var special = GetKeyValuePairSpceciality(doctorinfo.specialization);
        var docpubupdate = [];
        var docAch = [];
        var docEdu = [];
        var docSer = [];
        var docMem = [];
        var docAwa = [];
        var docSpe = [];
        var i;
        var areacode = 1;
        var statecode = 1;
        if (doctorinfo.MobileNumber.toString().length > 9) {
            statecode = parseFloat(doctorinfo.MobileNumber.toString().substring(0, 4));
            areacode = parseFloat(doctorinfo.MobileNumber.toString().substring(4, 10));
        }
        doctorDetails = {
            DoctorID: doctorinfo.doctorid,
            TermsAccepted: "Y",
            FirstName: doctorinfo.Name,
            FullName: doctorinfo.Name,
            SpecialityCD: special,
            Experience: parseInt(doctorinfo.Experience),
            UserPassword: doctorinfo.Userpassword,
            About: doctorinfo.About,
            Gender: doctorinfo.Gender,
            DOB: doctorinfo.DOB,
            RoleId: doctorinfo.RoleId,
            GroupId: doctorinfo.GroupId,
            MemberID: doctorinfo.MedicalRegNumber,
            Qualification: docQualificationCollection,
            Services: GetKeyValuePair(doctorinfo.Services),
            Membership: GetKeyValuePair(doctorinfo.Memberships),
            Awards: GetKeyValuePair(doctorinfo.Awards),
            SignOffPWDInd: doctorinfo.SignOffPWDInd,
            SignOffPassword: doctorinfo.SignOffPassword
        };
        params.UserEmail = [{
            EmailID: doctorinfo.Email,
            EmailIDType: 'P',
            PrimaryIND: "Y"
        }],
            params.UserPhone = [{
                "PhAreaCD": doctorinfo.PhAreaCD,
                "FullNumber": doctorinfo.MobileNumber,
                "PhCntryCD": doctorinfo.PhCntryCD,
                "PhNumber": doctorinfo.UserMobileNumber,
                "UserMobileNo": doctorinfo.UserMobileNo,
                "PhType": "M",
                "PrimaryIND": "Y",
                "PhStateCD": statecode
            }];
        for (i = 0; i < doctorinfo.UserPublishing.length; i++) {
            docpubupdate.push({
                RowID: i,
                Year: doctorinfo.UserPublishing[i].Year,
                Indicator: "P",
                Name: doctorinfo.UserPublishing[i].Name
            });
        }
        for (i = 0; i < doctorinfo.UserAchievements.length; i++) {
            docAch.push({
                RowID: i,
                Year: doctorinfo.UserAchievements[i].Year,
                Indicator: "A",
                Name: doctorinfo.UserAchievements[i].Name
            });
        }
        for (i = 0; i < doctorinfo.UserEducation.length; i++) {
            var YearOfPassedOutval = doctorinfo.UserEducation[i].edu_startyear + "-" + doctorinfo.UserEducation[i].edu_endyear;
            docEdu.push({
                RowID: i,
                EducationName: doctorinfo.UserEducation[i].EducationName,
                InstituteName: doctorinfo.UserEducation[i].InstituteName,
                YearOfPassedOut: YearOfPassedOutval,
                StartYear: doctorinfo.UserEducation[i].edu_startyear,
                EndYear: doctorinfo.UserEducation[i].edu_endyear
            });
        }
        for (i = 0; i < doctorinfo.Services.length; i++) {
            docSer.push({
                RowID: i,
                Indicator: "S",
                Name: doctorinfo.Services[i].Name
            });
        }
        for (i = 0; i < doctorinfo.Memberships.length; i++) {
            docMem.push({
                RowID: i,
                Indicator: "M",
                Name: doctorinfo.Memberships[i].Name
            });
        }
        for (i = 0; i < doctorinfo.Awards.length; i++) {
            docAwa.push({
                RowID: i,
                Indicator: "AW",
                Name: doctorinfo.Awards[i].Name
            });
        }
        for (i = 0; i < doctorinfo.specialization.length; i++) {
            docSpe.push({
                SerialNumber: i,
                SpecialityID: doctorinfo.specialization[i].SpecialityID,
                SpecialityDesc: doctorinfo.specialization[i].SpecialityDesc,
                SubSpecialityDesc: doctorinfo.specialization[i].SubSpecialityDesc
            });
        }
        var docEduQualification = [];
        for (i = 0; i < doctorinfo.UserEducation.length; i++) {
            docEduQualification.push({
                RowID: i,
                EducationName: doctorinfo.UserEducation[i].EducationName,
                InstituteName: doctorinfo.UserEducation[i].InstituteName,
                YearOfPassedOut: doctorinfo.UserEducation[i].FullName,
                StartYear: doctorinfo.UserEducation[i].edu_startyear,
                EndYear: doctorinfo.UserEducation[i].edu_endyear
            });
        }
        var docQualificationCollection = GetKeyValuePairEducationName(docEduQualification);
        var DoctorPublishing = docpubupdate;
        var DoctorAchievements = docAch;
        var DoctorEducation = docEdu;
        var DoctorServices = docSer;
        var DoctorMembership = docMem;
        var DoctorAwards = docAwa;
        var DoctorSpeciality = docSpe;
        params.UserDetails = doctorDetails;
        params.UserPublishing = DoctorPublishing;
        params.UserAchievements = DoctorAchievements;
        params.UserEducation = DoctorEducation;
        params.UserServices = DoctorServices;
        params.UserAwards = DoctorAwards;
        params.UserMembership = DoctorMembership;
        params.UserSpecilityDetails = DoctorSpeciality;
        params = JSON.stringify(params);
        params = params.replace(/'/g, "");
        params = "'" + params + "'";
        var urlpath = $http.post(url + "/Admin/UpdateUserProfile", params, header);
        urlpath.success(function (data) {
            callbackSuccess(data);
        }).error(function (data) {
            callbackError(data);
        });
    };

    function GetKeyValuePair(lists) {
        var items = {};
        var rowno = 1;
        angular.forEach(lists, function (item) {
            items[rowno] = item.name;
            rowno++;
        });
        return items;
    }
}]);
