    // Several controllers ask for the same credential on one page load - the shell on
    // every route change, the calling header on start-up and again when it restores
    // presence - so the same request went out several times over for one answer. Hand
    // them all the same in-flight promise, and keep the answer for a short while after
    // it lands. The activation heartbeat runs every 5 minutes, far outside this window,
    // so a credential deactivated by an admin is still noticed as quickly as before.
    var telnyxCredentialCache = {};
    var TELNYX_CREDENTIAL_TTL_MS = 30000;
    this.GetTelnyxUserCredentialsByBranchId = function (UserId, HospitalId) {
        var key = HospitalId + "|" + UserId;
        var hit = telnyxCredentialCache[key];
        if (hit && (Date.now() - hit.at) < TELNYX_CREDENTIAL_TTL_MS) {
            return hit.promise;
        }
        var promise = $http.get(url + "/Integration/GetTelnyxUserCredentialsByBranchId?HospitalId=" + HospitalId + "&UserId=" + UserId);
        telnyxCredentialCache[key] = { at: Date.now(), promise: promise };
        // a failed lookup must not be remembered - the next caller should try again
        promise.catch(function () { delete telnyxCredentialCache[key]; });
        return promise;
    };
    
