    this.AddUpdateCounsellorStatus = function (param, callbackSuccess, callbackError) {

        console.log(JSON.stringify(param));


        $http({
            method: "POST",
            url: url + "/Surgery/AddUpdateCounsellorStatus",
            headers: { "Content-Type": undefined },
            transformRequest: function (data) {
                var formData = new FormData();
                formData.append("model", angular.toJson(data.model));
                for (var i = 0; i < data.model.EducationMaterial.DocumentDetails.length; i++) {
                    formData.append("file1", data.model.EducationMaterial.DocumentDetails[i].file);
                }
                return formData;
            },
            data: { model: param, file: param.EducationMaterial.DocumentDetails }
        }).success(function (patData) {
            if (patData !== null && patData.ExceptionType !== "PSQLException") {
                callbackSuccess(patData);
            }
        }).error(function (patData) {
            callbackError(patData);
        });
    };

