    this.SaveAttachmentClaim = function (param, tempArray, callbackSuccess, callbackError) {



        if (tempArray.length > 0) {
            angular.forEach(tempArray, function (item) {
                if (item.AttachmentId === 0) {
                    param.PatientClaimAttachments.push(item);
                }
            });
        }

        var request = {
            "controlNumber": "123459999",
            "tradingPartnerServiceId": "9497",
            "submitter": {
                "organizationName": "happy doctors grouppractice",
                "etin": "1942788757"
            },
            "provider": {
                "organizationName": "happy doctors group",
                "npi": "1760854442",
                "address": {
                    "address1": "123 address1",
                    "city": "city1",
                    "state": "wa",
                    "postalCode": "981010000"
                },
                "phoneNumber": "123456789",
                "faxNumber": "123456789"
            },
            "subscriber": {
                "memberId": "0000000001",
                "firstName": "johnone",
                "lastName": "doeone"
            },
            "claimInformation": {
                "patientControlNumber": "12345",
                "beginClaimServiceDate": "20050513",
                "endClaimServiceDate": "20050514",
                "serviceLines": [
                    {
                        "payerClaimControlNumber": "123456789",
                        "serviceLineDateInformation": {
                            "submissionDate": "20050514"
                        },
                        "attachmentDetails": {
                            "name": "rightarm.jpg"
                        }
                    }
                ]
            }
        };


        $http({
            method: "POST",
            url: url + "/Insurance/UploadClaimAttachmentForaClaim",
            headers: { "Content-Type": undefined },
            transformRequest: function (data) {
                var formData = new FormData();
                formData.append("model", angular.toJson(request));
                for (var i = 0; i < data.model.PatientClaimAttachments.length; i++) {
                    formData.append("file", data.model.PatientClaimAttachments[i].file);
                }
                return formData;
            },
            data: { model: param, file: param.PatientClaimAttachments }
        }).success(function (patData) {
            if (patData !== null && patData.ExceptionType !== "PSQLException") {
                callbackSuccess(patData);
            }
        }).error(function (patData) {
            callbackError(patData);
        });
    };


    this.SaveClaimDetails = function (param, tempArray, callbackSuccess, callbackError) {

        param.InsuranceImageArray = [];
        if (tempArray.length > 0) {
            angular.forEach(tempArray, function (item) {
                if (item.DocumentId === 0) {
                    param.InsuranceImageArray.push(item);
                }
            });
        }

        param.InsuranceDetails.DocumentDetails = param.InsuranceImageArray;
        $http({
            method: "POST",
            url: url + "/Insurance/AddUpdateClaimDetails",
            headers: { "Content-Type": undefined },
            transformRequest: function (data) {
                var formData = new FormData();
                formData.append("model", angular.toJson(data.model));
                for (var i = 0; i < data.model.InsuranceDetails.DocumentDetails.length; i++) {
                    formData.append("file1", data.model.InsuranceDetails.DocumentDetails[i].file);
                }
                return formData;
            },
            data: { model: param, file: param.InsuranceDetails.DocumentDetails }
        }).success(function (patData) {
            if (patData !== null && patData.ExceptionType !== "PSQLException") {
                callbackSuccess(patData);
            }
        }).error(function (patData) {
            callbackError(patData);
        });
    };

