    this.getPatientRcopiaNotificationsCount = function (obj) {



        var lastApiCallTimestamp = eHnoteMasterDataService.getrcopiaNotificationTime();

        console.log(lastApiCallTimestamp + "__lastApiCallTimestamp");

        lastApiCallTimestamp.DateTime = lastApiCallTimestamp.DateTime || "";

        if (lastApiCallTimestamp.IsPrescriptionUpdated) {
            return $http.post(url + "/Consultation/getPatientRcopiaNotificationsCount", obj, header)
                .then(function (response) {

                    var objj = {
                        "DateTime": Date.now().toString(),
                        "IsPrescriptionUpdated": false
                    }
                    eHnoteMasterDataService.addrcopiaNotificationTime(objj);
                    return response.data;
                })
                .catch(function (error) {
                    console.error('Error:', error);
                    throw error;
                });
        } else {

            //if (lastApiCallTimestamp.DateTime == "" || Date.now() - parseInt(lastApiCallTimestamp) >= 15 * 60 * 1000) {
            //    return $http.post(url + "/Consultation/getPatientRcopiaNotificationsCount", obj, header)
            //        .then(function (response) {
            //            var objj = {
            //                "DateTime": Date.now().toString(),
            //                "IsPrescriptionUpdated": false
            //            }
            //            eHnoteMasterDataService.addrcopiaNotificationTime(objj);
            //            return response.data;
            //        })
            //        .catch(function (error) {
            //            console.error('Error:', error);
            //            throw error;
            //        });
            //}
            //else if (lastApiCallTimestamp.DateTime != "") {
            //    return $http.post(url + "/Consultation/getPatientRcopiaNotificationsCount", obj, header)
            //        .then(function (response) {
            //            var objj = {
            //                "DateTime": Date.now().toString(),
            //                "IsPrescriptionUpdated": false
            //            }
            //            eHnoteMasterDataService.addrcopiaNotificationTime(objj);
            //            return response.data;
            //        })
            //        .catch(function (error) {
            //            console.error('Error:', error);
            //            throw error;
            //        });
            //} else {
            //    var deferred = $q.defer();
            //    deferred.resolve('');
            //    return deferred.promise;
            //}

            if (!lastApiCallTimestamp || !lastApiCallTimestamp.DateTime || Date.now() - parseInt(lastApiCallTimestamp.DateTime) >= 15 * 60 * 1000) {
                // 15 minutes have passed, call API
                return $http.post(url + "/Consultation/getPatientRcopiaNotificationsCount", obj, header)
                    .then(function (response) {
                        var objj = {
                            "DateTime": Date.now().toString(),
                            "IsPrescriptionUpdated": false
                        };
                        eHnoteMasterDataService.addrcopiaNotificationTime(objj); // Save updated timestamp
                        return response.data;
                    })
                    .catch(function (error) {
                        console.error('Error:', error);
                        throw error;
                    });
            } else {

                var deferred = $q.defer();
                deferred.resolve('');
                return deferred.promise;
            }
        }


    };


