    //Saving Personal Details
    this.AddUpdatePatientRegisterFromPatientPortal = function (param, param1, callbackSuccess, callbackError) {
        $http({
            method: "POST",
            url: url + "/Patient/AddUpdatePatientRegisterFromPatientPortal",
            headers: { "Content-Type": undefined },
            transformRequest: function (data) {
                var formData = new FormData();
                formData.append("model", angular.toJson(data.model));

                //file1 -> referral letters
                var referralDocuments = data.file2.referralDocumentDetails || [];
                for (var r = 0; r < referralDocuments.length; r++) {
                    if (referralDocuments[r].file instanceof File) {
                        formData.append("file1", referralDocuments[r].file, referralDocuments[r].file.name);
                    }
                }

                //file2 -> profile picture
                var profilePicDetails = data.file2.patientProfilePicDetails || [];
                for (var i = 0; i < profilePicDetails.length; i++) {
                    if (profilePicDetails[i].file !== "" && profilePicDetails[i].file !== undefined) {
                        formData.append("file2", profilePicDetails[i].file);
                    }
                }
                return formData;
            },
            data: { model: param, file2: param1 }
        }).then(function (data, status) {
            callbackSuccess(data);
        }, function (data) {
            callbackError(data);
        });
    };

    //Saving Ros Data
    this.AddupdateROSDataFrompatientPortal = function (obj) {
        return $http.post(url + "/Patient/AddupdateROSDataFrompatientPortal", obj, header);
    };

    //Saving Insurance
    this.AddupdatePatientInsurancesFromPatientportal = function (param, callbackSuccess, callbackError) {



        $http({
            method: "POST",
            url: url + "/Patient/AddupdatePatientInsurancesFromPatientportal",
            headers: { "Content-Type": undefined },
            transformRequest: function (data) {
                var formData = new FormData();
                formData.append("model", angular.toJson(data.model));
                var docs = data.model.PatientInsuranceDetails[0].TempInsuranceImagesArray || [];

                docs.forEach(function (doc, i) {
                    if (doc.DocumentId === 0 && doc.file instanceof File) {
                        var ext = doc.file.name.split('.').pop();
                        var finalName = (doc.DisplayName || "File") + "." + ext;
                        formData.append("file" + (i + 1), doc.file, finalName);
                    }
                });
                /*for (var i = 0; i < data.model.PatientInsuranceDetails[0].PatientDocumentDetails.length; i++) {
                    if (data.model.PatientInsuranceDetails[0].PatientDocumentDetails[i].DocumentId === 0) {

                        if (data.model.PatientInsuranceDetails[0].PatientDocumentDetails[i].file != '') {
                            var value = data.model.PatientInsuranceDetails[0].PatientDocumentDetails[i].file.name;
                            var values = value.split(".");
                            var finalValue = "Front" + "." + values[1];
                            if (data.model.PatientInsuranceDetails[0].PatientDocumentDetails[i].IsBackSidefile) {
                                finalValue = "Back" + "." + values[1];
                            }

                            console.log(finalValue);
                            formData.append("file1", data.model.PatientInsuranceDetails[0].PatientDocumentDetails[i].file, finalValue);
                        }


                    }
                }*/
                return formData;
            },
            data: { model: param, file: param.PatientInsuranceDetails[0].PatientDocumentDetails }
        }).then(function (data, status) {
            callbackSuccess(data);
        }, function (data) {
            callbackError(data);
        });
    };

