    this.ValidateExpDate = function (ExpiryDate) {

        ExpiryDate = ExpiryDate || null;




        //ExpiryDate formate == 12/2015
        var object = { "IsInValid": false, "IsProper": true, "IsPastExpDate": false, "IsCurrentMonth": false };

        if (ExpiryDate === null) {
            object.IsInValid = true;
            return object;
        }
        if (!ExpiryDate.match(/^(\d{1,2})\/(\d{4})$/)) {
            object.IsInValid = true;
        }
        var ExpriryArray = ExpiryDate.split("/");
        var TempExpdate = ExpriryArray[1] + ExpriryArray[0];



        if (parseFloat(ExpriryArray[0]) > 12 || parseFloat(ExpriryArray[0]) === 0) {
            object.IsProper = false;
        }

        if (ExpriryArray.length > 1) {
            if (ExpriryArray[1].length !== 4) {
                object.IsProper = false;
            }
        }





        var CurrentYear = new Date().getFullYear().toString();
        var CurrentMonth = (new Date().getMonth() + 1).toString();


        CurrentMonth = CurrentMonth.length === 1 ? "0" + CurrentMonth : CurrentMonth;
        if (TempExpdate < (CurrentYear + CurrentMonth)) {
            object.IsPastExpDate = true;
        } else if (TempExpdate === (CurrentYear + CurrentMonth)) {
            object.IsCurrentMonth = true;
        }
        return object;
    };

    this.GetStockDetailsSum = function (StockDetailsArray) {
        var amount = 0;
        angular.forEach(StockDetailsArray, function (item, index) {
            amount += parseFloat(item.ActualCost) * parseFloat(item.NoOfUnits);
        });
        return amount;
    };
    this.CalculateSalesHistoryItem = function (consumeHistry) {
        consumeHistry.isReturn = false;
        var DiscountAmount = 0;
        var TotalAmount = consumeHistry.Quantity * consumeHistry.Price;
        if (consumeHistry.DiscountType === "P") {
            DiscountAmount = TotalAmount * consumeHistry.Discount / 100;
        } else {
            DiscountAmount = consumeHistry.Discount;
        }
        TotalAmount -= DiscountAmount;
        consumeHistry.ComputedPrice = TotalAmount / consumeHistry.Quantity;
        consumeHistry.TotalPrice = consumeHistry.Quantity * consumeHistry.ComputedPrice;
        return consumeHistry;
    };
    this.CheckZeroAmount = function (PaymentArray) {
        angular.forEach(PaymentArray, function (item, index) { item.Amount = parseFloat(item.Amount) || 0; });
        PaymentArray = $filter("filter")(PaymentArray, function (item, index) { return item.Amount !== 0; }) || [];
        return PaymentArray;
    };
