    this.CheckOpticalBarocdeItemSoldOrNot = function (object, OpticalConsumeId) {
        var status = false;

        if (OpticalConsumeId !== 0) {
            return status;
        }


        //var SoldArray = $filter("filter")(object.OpticalChildDetails[0].BarCodesArray, function (item, index) { return item.SaleId !== null; }) || [];
        //if (SoldArray.length !== 0) {
        //    status = true;
        //}
        if (object.OpticalChildDetails.length > 0) {
            object.OpticalChildDetails[0].BarCodesArray = object.OpticalChildDetails[0].BarCodesArray || [];
            var NotSoldArray = $filter("filter")(object.OpticalChildDetails[0].BarCodesArray, function (item, index) {
                return item.SaleId === null && item.PurchaseReturnId === null;
            }) || [];
            if (NotSoldArray.length !== 0) {
                angular.forEach(NotSoldArray, function (ite, ind) { ite.IsChecked = true; });
                status = false;
            } else {
                status = true;
            }
        } else { status = true; }



        return status;
    };


    this.GenerateNewBarCodesArray = function (OptStockDetail) {
        var BarCodeArrayLength = OptStockDetail.BarCodesArray.length;


        var AvailableBarCodesArray = $filter("filter")(OptStockDetail.BarCodesArray, function (iterator, index) { return iterator.SaleId === null; }) || [];


        if (BarCodeArrayLength === 0) {//No Barcodes exist in db
            for (var i = 0; i < OptStockDetail.Quantity; i++) {
                OptStockDetail.BarCodesArray.push({ "BarCode": null, "BarCodeId": null, "BarCodeDetailId": null, "DeleteInd": 0, "SaleId": null });
            }
        } else if (OptStockDetail.Quantity > BarCodeArrayLength) {//Quantity increased
            var IncreasedCount = OptStockDetail.Quantity - BarCodeArrayLength;
            for (var i = 0; i < IncreasedCount; i++) {
                OptStockDetail.BarCodesArray.push({ "BarCode": null, "BarCodeId": OptStockDetail.BarCodesArray[0].BarCodeId, "BarCodeDetailId": null, "DeleteInd": 0, "SaleId": null });
            }
        } else if (parseInt(OptStockDetail.Quantity) < AvailableBarCodesArray.length) {//Quantity decreased


            var DecreasedQuantity = AvailableBarCodesArray.length - parseInt(OptStockDetail.Quantity);

            for (var i = 0; i < DecreasedQuantity; i++) {


                var SelectedBarCodeObject = AvailableBarCodesArray[i];

                var BarCodeDetailIdIndex = OptStockDetail.BarCodesArray.findIndex(i => i.BarCodeDetailId === SelectedBarCodeObject.BarCodeDetailId);

                OptStockDetail.BarCodesArray[BarCodeDetailIdIndex].DeleteInd = true;
            }
        }



        return OptStockDetail.BarCodesArray || [];
    };
    this.CheckDcreasedBarCodesCount = function (OptStockDetail) {


        var IsQuantityAvailable = true;


        var BarCodeArrayLength = OptStockDetail.BarCodesArray.length;
        var AvailableBarCodesArray = $filter("filter")(OptStockDetail.BarCodesArray, function (iterator, index) { return iterator.SaleId === null; }) || [];

        if (parseInt(OptStockDetail.Quantity) > AvailableBarCodesArray.length) {//Increased quantity
            IsQuantityAvailable = true;
        }


        if (parseInt(OptStockDetail.Quantity) < AvailableBarCodesArray.length) {//Decreased quantity
            IsQuantityAvailable = true;
        }


        if (AvailableBarCodesArray.length === 0) {//No Barcodes
            IsQuantityAvailable = false;
        }



        return { "IsQuantityAvailable": IsQuantityAvailable, "AvailableBarCodesQuantity": AvailableBarCodesArray.length };
    };


    this.checkObjectEmpty = function (obj) {


        obj = obj || {};

        if (!angular.equals(obj, {})) {

            var count = 0;
            for (var prop in obj.Attributes) {
                if (obj.Attributes[prop] !== "" && obj.Attributes[prop] !== "Distance") {
                    count++;
                }
            }
            var LenseCoatingChecked = $filter("filter")(obj.LensCoating, { "IsActive": true }, true).length;
            var LenseTypeChecked = $filter("filter")(obj.LensType, { "IsActive": true }, true).length;
            if (LenseCoatingChecked !== 0 || LenseTypeChecked !== 0) {
                count++;
            }
            if (count !== 0) {
                return true;
            } else {
                return false;
            }

        }


    };
