    this.IsOpticalCheckBarCodeExist = function (Product, ConsumeStockDetails) {
        var Index = -1;
        var IsExist = false;


        var TempProductBarCodesArray = $filter("filter")(Product.BarCodesArray, { "IsChecked": true }, true) || [];


        var TempBarCodesArray = [], BarCodeExistCount = 0;
        angular.forEach(ConsumeStockDetails, function (item) { TempBarCodesArray = TempBarCodesArray.concat(item.BarCodesArray); });


        angular.forEach(TempProductBarCodesArray, function (item, ind) {
            BarCodeExistCount += $filter("filter")(TempBarCodesArray, { "BarCodeDetailId": item.BarCodeDetailId, "IsChecked": true }, true).length;
        });
        if (BarCodeExistCount > 0) {
            IsExist = true;
        }
        return IsExist;
    };

    this.SplitStockDetailsBasedOnBarCodeArray = function (Product) {

        var TempArray = [];

        if (Product.BarCodesArray.length === 0) {// No BarCodes Found

            TempArray.push(Product);

        } else {//BarCodes Found

            var SelectedBarCodesArray = $filter("filter")(Product.BarCodesArray, { "IsChecked": true }, true);
            for (var i = 0; i < SelectedBarCodesArray.length; i++) {
                var object = angular.copy(Product);
                object.BarCodesArray = [];
                object.BarCodesArray.push(SelectedBarCodesArray[i]);
                object.AvailableStockArray = [];
                object.OpticalStockDetailId = SelectedBarCodesArray[i].StockDetailId;
                object.Quantity = 1;
                object.TempEditQuantity = angular.copy(object.Quantity);
                TempArray.push(angular.copy(object));
            }
        }


        //var TempAvailableStockArray = $filter("filter")(Product.AvailableStockArray, function (item, index) {
        //    return item.OpticalStockDetailId !== Product.BarCodesArray[0].StockDetailId;
        //}) || [];



        angular.forEach(Product.AvailableStockArray, function (item, index) {
            item.EnteredQuantity = parseInt(item.EnteredQuantity) || 0;
            if (item.EnteredQuantity !== 0) {
                var object = angular.copy(Product);
                object.BarCodesArray = [];
                object.TempEditQuantity = angular.copy(item.Quantity);
                object.Quantity = item.EnteredQuantity;
                object.OpticalStockDetailId = item.OpticalStockDetailId;
                TempArray.push(angular.copy(object));
            }
        });



        return TempArray;
    };

