    this.FormateModels = function (Bathces, key, type) {
        Bathces = SurgeryStaticDataService.GroupBy(Bathces, key);
        var TempArray = [];

        if (type === "InventoryTransfer") {
            for (var k in Bathces) {
                var AvailableToReturn = 0;
                angular.forEach(Bathces[k], function (item, index) { AvailableToReturn += item.AvailableNoOfUnits || 0; });
                TempArray.push({
                    "BatchNumber": k,
                    "list": Bathces[k],
                    "AvailableToReturn": AvailableToReturn
                });
            }
        }
        if (type === "OtScreen") {
            for (var k in Bathces) {
                var AvailableStock = 0;
                angular.forEach(Bathces[k], function (item, index) { AvailableStock += item.AvailableStock || 0; });
                TempArray.push({
                    "BatchNumber": k,
                    "list": Bathces[k],
                    "AvailableStock": AvailableStock
                });
            }
        }


        return TempArray;
    };

