function GetKeyValuePairEducationName(lists) {
    var items = {};
    var rowno = 1;
    angular.forEach(lists, function (item) {
        items[rowno] = item.EducationName;
        rowno++;
    });
    return items;
}
eHnoteServices.factory("datapersistanceFactory", [function () {
    return {
        getItem: function (key) {
            var returnobj = [];
            var value = localStorage.getItem(key);
            //if (key == "JWTToken") {
            //    value = null;
            //}
            if (value === "undefined" || value === null || value === "") {
                returnobj = [];
            } else {
                returnobj = JSON.parse(value);
            }
            return returnobj;
        },
        getItemString: function (key) {
            var returnobj = [];
            var value = localStorage.getItem(key);
            if (value === "undefined" || value === null || value === "") {
                returnobj = [];
            } else {
                returnobj = value;
            }
            return returnobj;
        },
        set: function (key, value) {
            localStorage.setItem(key, JSON.stringify(value));
        },
        remove: function (key) {
            localStorage.removeItem(key);
        },
        clearAll: function () {
            localStorage.clear();
        }
    };
}]);

