eHnoteServices.factory("eHnoteLoginStatusService", ['datacookieFactory', "loginCookieFactory", function (datacookieFactory, loginCookieFactory) {
    var loggedIn = 'false';


    var newLoginDetailsObj = {
        "JToken": "",
        "RToken": "",
        "TokenExpiry": "",
        "UserId": "",
        "UserName": "",
        "HashPassword": "",
        "loggedinStatus": false,
        "LoginTab": "",
        "LoginBranchId": "",
        "displayName": "",
        "RoleID": "",
        "RememberCredentials": "",
        "SubOrganizationId": ""
    }
    var addUserLoginDetails = function (data) {
        newLoginDetailsObj = data;
        loginCookieFactory.set('loggedInfo', newLoginDetailsObj);
    };
    var getUserLoginDetails = function () {

        var logdata = loginCookieFactory.getItem('loggedInfo');
        if (logdata === null) {
            newLoginDetailsObj = {
                "JToken": "",
                "RToken": "",
                "TokenExpiry": "",
                "UserId": "",
                "UserName": "",
                "HashPassword": "",
                "loggedinStatus": false,
                "LoginTab": "",
                "LoginBranchId": "",
                "displayName": "",
                "RoleID": "",
                "RememberCredentials": "",
                "SubOrganizationId": ""
            }
        }

        newLoginDetailsObj = (loginCookieFactory.getItem('loggedInfo') === null) ? newLoginDetailsObj : loginCookieFactory.getItem('loggedInfo');
        return newLoginDetailsObj;
    };


    var newtelynxUserLoginDetailsObj = {
        "JToken": "",
        "UserId": "",
        "loggedinStatus": false,
        "LoginTab": "",
        "LoginBranchId": "",
        "UserCredentialId": "",
        "FromNumber": "",
        "RoleId": ""
    }
    var addTelynxUserLoginDetails = function (data) {
        newtelynxUserLoginDetailsObj = data;
        loginCookieFactory.set('telnyxloggedInfo', newtelynxUserLoginDetailsObj);
    };

    var getTelynxUserLoginDetails = function () {

        var tellogdata = loginCookieFactory.getItem('telnyxloggedInfo');
        if (tellogdata === null) {
            newtelynxUserLoginDetailsObj = {
                "JToken": "",
                "UserId": "",
                "loggedinStatus": false,
                "LoginTab": "",
                "LoginBranchId": "",
                "FromNumber": "",
                "UserCredentialId": "",
                "RoleId": ""
            }
        }

        newtelynxUserLoginDetailsObj = (loginCookieFactory.getItem('telnyxloggedInfo') === null) ? newtelynxUserLoginDetailsObj : loginCookieFactory.getItem('telnyxloggedInfo');
        return newtelynxUserLoginDetailsObj;
    };

    return {
        "addUserLoginDetails": addUserLoginDetails,
        "getUserLoginDetails": getUserLoginDetails,
        "addTelynxUserLoginDetails": addTelynxUserLoginDetails,
        "getTelynxUserLoginDetails": getTelynxUserLoginDetails,
        "getStatus": function () {
            return loggedIn;
        },
        "setStatus": function (value) {
            loggedIn = value;
            newLoginDetailsObj.loggedinStatus = loggedIn;
        }
    };
}]);
