// Task 13 - Order Given By details on medication timings (DropTimings) are validated with the Given By user's
// passcode (the chart-signing passcode, checked by Surgery/GetUserValidatePassword). Editing a validated timing
// opens it locked; the previous Given By user's passcode unlocks it for changes.
// attach($scope) adds the row handlers used by the DropTimingGivenBy partials. UI-only fields are prefixed with $$
// so angular.toJson drops them from save payloads; passcodes are cleared right after every validation attempt.
eHnoteServices.service("DropTimingGivenByService", ["$filter", "alertify", "eHnoteSurgeryService", function ($filter, alertify, eHnoteSurgeryService) {

    var DropTimingGivenBySelf = this;

    // Timings that are still on the Add / locked screen (not validated) - saving must be blocked while any exist.
    this.GetNotValidatedCount = function (DropTimings) {
        return (DropTimings || []).filter(function (x) { return x.DeleteInd !== 'Y' && !x.IsEditview; }).length;
    };

    // Custom (General) orders marked Done but not yet validated with the Given By passcode.
    /* A custom order that came back from the server already Done was validated when it was
       recorded, so it opens in the summary view. IsEditview is only ever undefined for those
       rows - Done / Not Done always sets it - which is what makes this safe to resolve here. */
    this.ResolveGeneralOrderValidated = function (Aitem) {
        if (!Aitem) { return false; }
        if (Aitem.IsEditview === undefined) {
            Aitem.IsEditview = !!(Aitem.GeneralOrderId && Aitem.Status == 'Done' && Aitem.GivenBy);
        }
        return Aitem.IsEditview === true;
    };

    this.GetNotValidatedGeneralOrdersCount = function (GeneralOrders) {
        let self = this;
        return (GeneralOrders || []).filter(function (x) {
            if (x.DeleteInd === 'Y' || x.Status != 'Done') { return false; }
            return !self.ResolveGeneralOrderValidated(x);
        }).length;
    };

    // Same count over the GeneralOrders of every OrderDetails row of one MedTypeId.
    this.GetNotValidatedGeneralOrdersInOrders = function (OrderDetails, MedTypeId) {
        let self = this, count = 0;
        angular.forEach(OrderDetails || [], function (Mitem) {
            if (Mitem.MedTypeId != MedTypeId) { return; }
            count += self.GetNotValidatedGeneralOrdersCount(Mitem.GeneralOrders);
        });
        return count;
    };


    // Same count over OrderDetails rows of one MedTypeId, e.g. (PreOpObj.OrderDetails, 2, 'DilationMedications').
    this.GetNotValidatedCountInOrders = function (OrderDetails, MedTypeId, MedicationsKey) {
        let self = this, count = 0;
        angular.forEach(OrderDetails || [], function (Mitem) {
            if (Mitem.MedTypeId != MedTypeId) { return; }
            angular.forEach(Mitem[MedicationsKey] || [], function (item) {
                if (item.DeleteInd !== 'Y') { count += self.GetNotValidatedCount(item.DropTimings); }
            });
        });
        return count;
    };

    var EmptyGivenByList = [];

    this.attach = function ($scope) {
        // The partial names its Given By list (e.g. 'MedicationGivenByNurseArray'); resolved on every digest
        // so a list built or rebuilt after the row renders is still picked up.
        $scope.GetDropGivenByList = function (ListName) {
            return $scope.$eval(ListName) || EmptyGivenByList;
        };

        $scope.ValidateDropGivenByPasscode = function (GivenBy, Password) {
            let reqObj = {
                "Password": Password,
                "UserId": $scope.UserId,
                "ReviewedBy": GivenBy,
                "OrganizationId": $scope.HospitalId
            };
            return eHnoteSurgeryService.GetUserValidatePassword(reqObj).then(function (resp) {
                return resp.data.status === "Success";
            });
        };

        $scope.ValidateDropGivenBy = function (kitem) {
            kitem.MedicationTime = kitem.MedicationTime || '';
            if (kitem.MedicationTime == '') {
                alertify.error("Please enter time!");
                return false;
            }
            kitem.GivenBy = kitem.GivenBy || null;
            if (kitem.GivenBy == null) {
                alertify.error("Please Select GivenBy for Medications!");
                return false;
            }
            if (!kitem.$$GivenByPassword) {
                alertify.error("Please Enter Password");
                return false;
            }
            $scope.ValidateDropGivenByPasscode(kitem.GivenBy, kitem.$$GivenByPassword).then(function (isValid) {
                kitem.$$GivenByPassword = '';
                if (!isValid) {
                    alertify.error("Invalid Password!");
                    return;
                }
                let GivenByUser = $filter('filter')($scope.allUserList || [], { 'DoctorID': kitem.GivenBy }, true)[0] || {};
                kitem.GivenByname = GivenByUser.FullName || '';
                kitem.LicenseNumber = GivenByUser.LicenseNumber || '';
                // An unsaved timing can still be removed after validating it.
                kitem.IsEditDrop = kitem.IsEditDrop || !kitem.DropTimingId;
                kitem.IsEditview = true;
                $scope.ResetDropGivenByEdit(kitem);
                alertify.success("Successfully Validated!");
            }, function () {
                kitem.$$GivenByPassword = '';
                alertify.error("Fetching data failed!");
            });
        };

        $scope.EditDropGivenBy = function (kitem) {
            kitem.$$Backup = {
                "MedicationDosage": kitem.MedicationDosage,
                "MedicationTime": kitem.MedicationTime,
                "GivenBy": kitem.GivenBy,
                "GivenByname": kitem.GivenByname,
                "LicenseNumber": kitem.LicenseNumber,
                "Remarks": kitem.Remarks
            };
            kitem.$$IsEditMode = true;
            kitem.$$PrevGivenBy = kitem.GivenBy || null;
            kitem.$$PrevGivenByName = kitem.GivenByname || '';
            // Dose, Time and Given By stay disabled until the previous Given By user's passcode is validated.
            kitem.$$IsLocked = kitem.$$PrevGivenBy != null;
            kitem.$$GivenByPassword = '';
            kitem.IsEditview = false;
        };

        $scope.ValidatePrevGivenBy = function (kitem) {
            if (!kitem.$$GivenByPassword) {
                alertify.error("Please Enter Password");
                return false;
            }
            $scope.ValidateDropGivenByPasscode(kitem.$$PrevGivenBy, kitem.$$GivenByPassword).then(function (isValid) {
                kitem.$$GivenByPassword = '';
                if (!isValid) {
                    // Wrong passcode - stay on the locked screen.
                    alertify.error("Invalid Password!");
                    return;
                }
                kitem.$$IsLocked = false;
                alertify.success("Validated! Make the changes and validate with the Given By password.");
            }, function () {
                kitem.$$GivenByPassword = '';
                alertify.error("Fetching data failed!");
            });
        };

        $scope.CancelEditDropGivenBy = function (kitem) {
            angular.extend(kitem, kitem.$$Backup || {});
            kitem.IsEditview = true;
            $scope.ResetDropGivenByEdit(kitem);
        };

        $scope.ResetDropGivenByEdit = function (kitem) {
            delete kitem.$$Backup;
            kitem.$$IsEditMode = false;
            kitem.$$IsLocked = false;
            kitem.$$GivenByPassword = '';
        };

        /* ------------------------------------------------------------------ Task 13 -
           Custom (General) orders marked Done are validated with the Given By user's
           passcode too, exactly like a medication timing. Same $$ UI-only fields, same
           lock-on-edit rule. A Done order is "validated" once Aitem.IsEditview is true. */

        $scope.IsGeneralOrderValidated = function (Aitem) {
            var IsValidated = DropTimingGivenBySelf.ResolveGeneralOrderValidated(Aitem);
            /* a row restored from the server may carry only the Given By id - fill the name and
               licence once so the summary reads the same as it did when it was recorded */
            if (IsValidated && !Aitem.$NameResolved && !Aitem.GivenByname) {
                Aitem.$NameResolved = true;
                var GivenByUser = $filter("filter")($scope.allUserList || [], { "DoctorID": Aitem.GivenBy }, true)[0] || {};
                Aitem.GivenByname = GivenByUser.FullName || "";
                Aitem.LicenseNumber = Aitem.LicenseNumber || GivenByUser.LicenseNumber || "";
            }
            return IsValidated;
        };

        $scope.ValidateGeneralOrderGivenBy = function (Aitem) {
            Aitem.MedicationTime = Aitem.MedicationTime || '';
            if (Aitem.MedicationTime == '') {
                alertify.error("Please enter time!");
                return false;
            }
            Aitem.GivenBy = Aitem.GivenBy || null;
            if (Aitem.GivenBy == null) {
                alertify.error("Please Select GivenBy for Custom Orders!");
                return false;
            }
            if (!Aitem.$$GivenByPassword) {
                alertify.error("Please Enter Password");
                return false;
            }
            $scope.ValidateDropGivenByPasscode(Aitem.GivenBy, Aitem.$$GivenByPassword).then(function (isValid) {
                Aitem.$$GivenByPassword = '';
                if (!isValid) {
                    alertify.error("Invalid Password!");
                    return;
                }
                let GivenByUser = $filter('filter')($scope.allUserList || [], { 'DoctorID': Aitem.GivenBy }, true)[0] || {};
                Aitem.GivenByname = GivenByUser.FullName || '';
                Aitem.LicenseNumber = GivenByUser.LicenseNumber || '';
                Aitem.IsEditview = true;
                $scope.ResetGeneralOrderGivenByEdit(Aitem);
                alertify.success("Successfully Validated!");
            }, function () {
                Aitem.$$GivenByPassword = '';
                alertify.error("Fetching data failed!");
            });
        };

        $scope.EditGeneralOrderGivenBy = function (Aitem) {
            Aitem.$$Backup = {
                "MedicationTime": Aitem.MedicationTime,
                "GivenBy": Aitem.GivenBy,
                "GivenByname": Aitem.GivenByname,
                "LicenseNumber": Aitem.LicenseNumber
            };
            Aitem.$$IsEditMode = true;
            Aitem.$$PrevGivenBy = Aitem.GivenBy || null;
            Aitem.$$PrevGivenByName = Aitem.GivenByname || '';
            /* Time and Given By stay disabled until the previous Given By user's passcode is validated. */
            Aitem.$$IsLocked = Aitem.$$PrevGivenBy != null;
            Aitem.$$GivenByPassword = '';
            Aitem.IsEditview = false;
        };

        $scope.ValidatePrevGeneralOrderGivenBy = function (Aitem) {
            if (!Aitem.$$GivenByPassword) {
                alertify.error("Please Enter Password");
                return false;
            }
            $scope.ValidateDropGivenByPasscode(Aitem.$$PrevGivenBy, Aitem.$$GivenByPassword).then(function (isValid) {
                Aitem.$$GivenByPassword = '';
                if (!isValid) {
                    alertify.error("Invalid Password!");
                    return;
                }
                Aitem.$$IsLocked = false;
                alertify.success("Validated! Make the changes and validate with the Given By password.");
            }, function () {
                Aitem.$$GivenByPassword = '';
                alertify.error("Fetching data failed!");
            });
        };

        $scope.CancelEditGeneralOrderGivenBy = function (Aitem) {
            angular.extend(Aitem, Aitem.$$Backup || {});
            Aitem.IsEditview = true;
            $scope.ResetGeneralOrderGivenByEdit(Aitem);
        };

        $scope.ResetGeneralOrderGivenByEdit = function (Aitem) {
            delete Aitem.$$Backup;
            Aitem.$$IsEditMode = false;
            Aitem.$$IsLocked = false;
            Aitem.$$GivenByPassword = '';
        };

        /* Called from the section's Done / Not Done handler so the two stay in step:
           Done re-opens the row for validation, Not Done clears everything. */
        $scope.ResetGeneralOrderValidation = function (Aitem, IsDone) {
            if (!Aitem) { return; }
            if (!IsDone) {
                Aitem.GivenByname = '';
                Aitem.LicenseNumber = '';
            }
            Aitem.IsEditview = false;
            delete Aitem.$$Backup;
            Aitem.$$IsEditMode = false;
            Aitem.$$IsLocked = false;
            Aitem.$$GivenByPassword = '';
        };
    };
}]);
